function once(fn) {
  var called = false;
  var result;
  return function () {
    if (!called) {
      called = true;
      result = fn.apply(this, arguments);
    }
    return result;
  };
}

var init = once(function () {
  console.log("initializing");
  return 42;
});
init();
init();
